    h, w = len(grid), len(grid[0])
    seen = set()
    largest_color = None
    largest_size = -1
    for r in range(h):
        for c in range(w):
            if (r, c) in seen:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen.add((r, c))
            size = 0
